actions.action:
// Economic nexus established per Wayfair - filing required
// MA threshold: $500,000 in gross receipts
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate state additions (MA-specific)
            double additions = 0.0;

            // MA requires addback of federal interest (U.S. obligations)
            // additions += revenue.federal_bond_interest;

            // MA requires addback of IRC 199A deduction (MA doesn't conform)
            // additions += result.section_199a_deduction;

            // MA requires addback of certain depreciation differences
            // additions += result.federal_ma_depreciation_difference;

            apportionment.state_additions = additions;

            // Calculate state subtractions (MA-specific)
            double subtractions = 0.0;

            // MA allows deduction for dividends from 15%+ owned subsidiaries
            // subtractions += revenue.qualified_dividend_deduction;

            // MA allows deduction for certain capital gains on qualified investments
            // subtractions += result.ma_qualified_capital_gain;

            // MA NOL deduction (limited to certain years)
            // subtractions += result.ma_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // MA uses 8% flat rate on apportioned net income
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract state credits (EDIP, R&D, film credits, etc.)
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
